#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int rule110(int left, int center, int right) {
    int rule[8] = {0, 1, 1, 1, 1, 1, 1, 0};
    return rule[(left << 2) | (center << 1) | right];
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }
    int generations = atoi(argv[1]);
    char *initial_state = argv[2];
    int length = strlen(initial_state);
    char *current_state = malloc(length + 1);
    strcpy(current_state, initial_state);
    for (int i = 0; i < generations; i++) {
        char *next_state = malloc(length + 1);
        for (int j = 0; j < length; j++) {
            int left = (j == 0) ? 0 : current_state[j - 1] - '0';
            int center = current_state[j] - '0';
            int right = (j == length - 1) ? 0 : current_state[j + 1] - '0';
            next_state[j] = rule110(left, center, right) + '0';
        }
        next_state[length] = '\0';
        printf("%s\n", next_state);
        free(current_state);
        current_state = next_state;
    }
    free(current_state);
    return 0;
}
